import{_ as r,o as t,c as a,a0 as n}from"./chunks/framework.BPYRhTv9.js";const h=JSON.parse('{"title":"Trust Center","description":"","frontmatter":{"title":"Trust Center"},"headers":[],"relativePath":"product-guide/trust-center.md","filePath":"product-guide/trust-center.md"}'),s={name:"product-guide/trust-center.md"};function o(i,e,l,c,d,p){return t(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="trust-center" tabindex="-1">Trust Center <a class="header-anchor" href="#trust-center" aria-label="Permalink to &quot;Trust Center&quot;">​</a></h1><blockquote><p>The services we rely on to run Wibe Stories, what they do, and how your data is handled.</p></blockquote><h2 id="hosting-and-infrastructure" tabindex="-1">Hosting and Infrastructure <a class="header-anchor" href="#hosting-and-infrastructure" aria-label="Permalink to &quot;Hosting and Infrastructure&quot;">​</a></h2><p><a href="https://vercel.com" target="_blank" rel="noreferrer"><img src="https://cdn.simpleicons.org/vercel" alt="Vercel"></a> <strong>Vercel</strong> — App hosting, serverless functions, edge network, and blob storage for card images and voice files.</p><p><a href="https://upstash.com" target="_blank" rel="noreferrer"><img src="https://cdn.simpleicons.org/upstash" alt="Upstash"></a> <strong>Upstash</strong> — Redis data store for daily usage limits, rate limiting, session state, and email subscriptions.</p><p><a href="https://neon.tech" target="_blank" rel="noreferrer"><img src="https://cdn.simpleicons.org/neon" alt="Neon"></a> <strong>Neon</strong> — Postgres database for Wibe Vault card storage (Pro users).</p><h2 id="speech-and-language" tabindex="-1">Speech and Language <a class="header-anchor" href="#speech-and-language" aria-label="Permalink to &quot;Speech and Language&quot;">​</a></h2><p><a href="https://deepgram.com" target="_blank" rel="noreferrer"><img src="https://cdn.simpleicons.org/deepgram" alt="Deepgram"></a> <strong>Deepgram</strong> — Speech-to-text transcription (Nova-3) for live recordings and uploaded audio.</p><p><a href="https://openrouter.ai" target="_blank" rel="noreferrer"><img src="https://cdn.simpleicons.org/openrouter" alt="OpenRouter"></a> <strong>OpenRouter</strong> — AI model gateway for tone rewrites. Routes each request to the best available language model.</p><h2 id="payments-and-email" tabindex="-1">Payments and Email <a class="header-anchor" href="#payments-and-email" aria-label="Permalink to &quot;Payments and Email&quot;">​</a></h2><p><a href="https://buymeacoffee.com" target="_blank" rel="noreferrer"><img src="https://cdn.simpleicons.org/buymeacoffee" alt="Buy Me a Coffee"></a> <strong>Buy Me a Coffee</strong> — Payment processing for Wibe Pass purchases and gift cards.</p><p><a href="https://resend.com" target="_blank" rel="noreferrer"><img src="https://cdn.simpleicons.org/resend" alt="Resend"></a> <strong>Resend</strong> — Transactional email delivery for Pro key recovery and occasion reminders.</p><h2 id="monitoring" tabindex="-1">Monitoring <a class="header-anchor" href="#monitoring" aria-label="Permalink to &quot;Monitoring&quot;">​</a></h2><p><a href="https://sentry.io" target="_blank" rel="noreferrer"><img src="https://cdn.simpleicons.org/sentry" alt="Sentry"></a> <strong>Sentry</strong> — Error monitoring and session replay. Data scrubbing is enabled to redact sensitive information.</p><hr><p>Wibe Stories is an independent project by Yellow Green Labs. It is not affiliated with any of the services listed above.</p>',16)])])}const u=r(s,[["render",o]]);export{h as __pageData,u as default};
